const response = $input.first().json;
let top3 = [];
try {
  const text = response.candidates[0].content.parts[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    top3 = parsed.top3 || [];
  }
} catch(e) {
  console.log('Parse error:', e.message);
  top3 = [
    { title: 'Sérum Vitamine C Anti-âge 30ml', price: '24.99', score: 88, why_viral: 'Transformation visible', hook: 'Ce sérum a transformé ma peau en 7 jours', category: 'beauty', commission_rate: 4, platform: 'amazon_fr' },
    { title: 'Écouteurs Sans Fil Bluetooth 5.3', price: '35.99', score: 82, why_viral: 'Unboxing satisfaisant', hook: 'Ces écouteurs changent tout', category: 'electronics', commission_rate: 3, platform: 'amazon_fr' },
    { title: 'Organisateur Maquillage Rotatif', price: '22.99', score: 79, why_viral: 'Révélation organisation', hook: 'Mon dressing avant/après', category: 'home', commission_rate: 8, platform: 'aliexpress' }
  ];
}
return top3.map((p, i) => ({
  json: {
    platform: p.platform || 'amazon_fr',
    title: p.title,
    price: parseFloat(p.price) || 0,
    commission_rate: p.commission_rate || 4,
    category: p.category || 'general',
    score: p.score || 80,
    affiliate_link: '',
    rank: i + 1,
    why_viral: p.why_viral || '',
    hook: p.hook || '',
    selected_at: new Date().toISOString()
  }
}));
